/**
 * Find the nearest index on a polyline for a given coordinate.
 */
function findNearestIndexOnPolyline(lat, lng, polyline) {
  let bestIdx = 0;
  let minDist = Infinity;
  for (let i = 0; i < polyline.length; i++) {
    const p = polyline[i];
    const d = (p[0] - lat) ** 2 + (p[1] - lng) ** 2;
    if (d < minDist) {
      minDist = d;
      bestIdx = i;
    }
  }
  return bestIdx;
}

/**
 * Get the exact road polyline for a corridor ID or 'ALL' / 'NH-44'.
 * Returns an array of [lat, lng] coordinates that follow the physical highway road.
 */
export function getCorridorExactPath(corridorId) {
  if (!corridorId || corridorId === 'ALL' || corridorId === 'NH-44') {
    return NH44_MASTER_ROAD_POLYLINE;
  }
  if (CORRIDOR_EXACT_GEOMETRIES[corridorId]) {
    return CORRIDOR_EXACT_GEOMETRIES[corridorId];
  }
  // Handle 'COR 01', 'COR-01', 'CORRIDOR 01'
  const normalized = corridorId.replace(/^COR(\s|-)?/i, 'CORRIDOR-');
  if (CORRIDOR_EXACT_GEOMETRIES[normalized]) {
    return CORRIDOR_EXACT_GEOMETRIES[normalized];
  }
  return NH44_MASTER_ROAD_POLYLINE;
}

/**
 * Snap any arbitrary coordinate to the nearest point on the NH-44 highway centerline.
 */
export function snapToNH44Road(lat, lng) {
  const idx = findNearestIndexOnPolyline(lat, lng, NH44_MASTER_ROAD_POLYLINE);
  return NH44_MASTER_ROAD_POLYLINE[idx];
}

/**
 * Slice an exact road trajectory between two coordinates along the NH-44 highway.
 * Returns the exact road curves between start and end.
 */
export function getHighwaySegmentBetweenPoints(lat1, lng1, lat2, lng2) {
  const idx1 = findNearestIndexOnPolyline(lat1, lng1, NH44_MASTER_ROAD_POLYLINE);
  const idx2 = findNearestIndexOnPolyline(lat2, lng2, NH44_MASTER_ROAD_POLYLINE);
  
  if (idx1 === idx2) {
    return [NH44_MASTER_ROAD_POLYLINE[idx1]];
  }
  if (idx1 < idx2) {
    return NH44_MASTER_ROAD_POLYLINE.slice(idx1, idx2 + 1);
  } else {
    return NH44_MASTER_ROAD_POLYLINE.slice(idx2, idx1 + 1).reverse();
  }
}
